 for(const name of METADATA_NAMES){const target=plan.assets.find(asset=>asset.name===name),text=plan.inlineMetadata[name];need(typeof text==='string'&&text.length<=2*1024*1024&&/^[A-Za-z0-9+/]+={0,2}$/.test(text),'metadata-inline-invalid');const bytes=Buffer.from(text,'base64');need(bytes.length===target.size&&bytes.length<=1024*1024&&sha256(bytes)===target.sha256,'metadata-inline-bytes-mismatch');}
 need(Array.isArray(plan.reuseOnlyNames)&&new Set(plan.reuseOnlyNames).size===plan.reuseOnlyNames.length&&plan.reuseOnlyNames.every(name=>seen.has(name)),'reuse-only-set-invalid');
 need(Array.isArray(plan.recoveryAuthorizedNames)&&new Set(plan.recoveryAuthorizedNames).size===plan.recoveryAuthorizedNames.length&&plan.recoveryAuthorizedNames.every(name=>seen.has(name)&&!plan.reuseOnlyNames.includes(name)),'recovery-name-set-invalid');
 need(Array.isArray(plan.priorUploadReservations)&&plan.priorUploadReservations.length<=plan.reuseOnlyNames.length+plan.recoveryAuthorizedNames.length,'prior-reservation-set-invalid');
 for(const row of plan.priorUploadReservations)need([...plan.reuseOnlyNames,...plan.recoveryAuthorizedNames].includes(row.name)&&/^[a-f0-9]{64}$/.test(row.sha256||'')&&row.file===`github-upload-${row.name}.attempt.json`,'prior-reservation-invalid');
 need(new Set(plan.priorUploadReservations.map(row=>row.name)).size===plan.priorUploadReservations.length,'prior-reservation-duplicate');
 need(JSON.stringify(plan.recoveryAuthorizedNames)===JSON.stringify([PACKAGE_NAMES[3]])&&plan.recoveryAuthorization?.generation===5&&plan.recoveryAuthorization.authorizedBy==='/root'&&['authorizationSha256','terminalProofSha256','cleanupReceiptSha256','originalAttemptSha256'].every(key=>/^[a-f0-9]{64}$/.test(plan.recoveryAuthorization[key]??''))&&plan.recoveryAuthorization.actualHistoricalHttpPostCount==='unknown','gen5-recovery-root-proof-missing');need(JSON.stringify(plan.reuseOnlyNames)===JSON.stringify(PACKAGE_NAMES.slice(0,3)),'continuation-reuse-set-invalid');
 need(plan.fastOriginalCloud?.originalRunId===37419799452&&plan.fastOriginalCloud.originalHead==='d4ec0b348e5d7c2710394c695adf745202d94763'&&['originalLogSha256','originalEvidenceSha256','originalCandidateFileSha256','originalRunnerSha256'].every(key=>/^[a-f0-9]{64}$/.test(plan.fastOriginalCloud[key]??'')),'original-cloud-proof-missing');
 const continuation=plan.continuationOriginalCloud;need(continuation?.stoppedRunId===37438906433&&continuation.stoppedHead==='22267c5d2bf4399756592d3432d7e0e7ed29d7e4'&&['stoppedLogSha256','stoppedEvidenceSha256','stoppedCandidateFileSha256','stoppedRunnerSha256','stoppedRangeSha256'].every(key=>/^[a-f0-9]{64}$/.test(continuation[key]??'')),'continuation-cloud-proof-missing');
 need(Array.isArray(continuation.completedAssets)&&continuation.completedAssets.length===3&&JSON.stringify(continuation.completedAssets.map(row=>row.name))===JSON.stringify(PACKAGE_NAMES.slice(0,3)),'continuation-completed-set-mismatch');
 for(const row of continuation.completedAssets){const target=plan.assets.find(target=>target.name===row.name);need(Number.isSafeInteger(row.id)&&row.id>0&&row.size===target.size&&row.sha256===target.sha256&&row.priorMirrorEvent?.stage==='mirror-bytes-verified'&&row.priorMirrorEvent.name===row.name&&row.priorMirrorEvent.bytes===target.size&&row.priorMirrorEvent.sha256===target.sha256&&[37424105405,37438906433].includes(row.previousRunId)&&/^[a-f0-9]{64}$/.test(row.previousCloudLogSha256??'')&&row.officialReadbackRunId===37438906433&&row.officialReadbackCloudLogSha256===continuation.stoppedLogSha256,'continuation-completed-bytes-mismatch');}need(new Set(continuation.completedAssets.map(row=>row.id)).size===3,'continuation-completed-id-duplicate');
 need(plan.continuationAuthorization?.generation===5&&plan.continuationAuthorization.authorizedBy==='/root'&&['authorizationSha256','stoppedEvidenceSha256'].every(key=>/^[a-f0-9]{64}$/.test(plan.continuationAuthorization[key]??''))&&plan.continuationAuthorization.stoppedEvidenceSha256===continuation.stoppedEvidenceSha256,'continuation-root-authorization-missing');
